testcase.name:
test_trajectories_agree_with_the_exact_density_matrix[OPENQASM 2.0;
include "qelib1.inc";
qreg q[3]; creg c[3];
h q[0];
cx q[0],q[1];
cx q[1],q[2];
rx(0.7) q[2];
measure q -> c;
]

test_trajectories_agree_with_the_exact_density_matrix[OPENQASM 2.0;
include "qelib1.inc";
qreg q[3]; creg a[1]; creg c[2];
h q[0];
cx q[0],q[1];
measure q[0] -> a[0];
if (a == 1) x q[2];
reset q[0];
h q[0];
measure q[1] -> c[0];
measure q[2] -> c[1];
]

test_semantic_errors[OPENQASM 2.0;
include "qelib1.inc";
qreg q[2];
cx q[0], q[2];-out of range]

test_semantic_errors[OPENQASM 2.0;
include "qelib1.inc";
qreg a[2]; qreg b[3];
cx a, b;-mismatched sizes]

test_semantic_errors[OPENQASM 2.0;
include "qelib1.inc";
qreg q[1]; creg c[2];
measure q -> c;-mismatched sizes]

test_unsupported_features[OPENQASM 3.0;
include "stdgates.inc";
qubit[2] q;
for int i in [0:1] { h q[i]; }]
